for(const c of coinItems){if(c.taken)continue;const cy=c.y+Math.sin(elapsed*3+c.phase)*4;if(Math.abs(p.x+p.w/2-c.x)<24&&Math.abs(p.y+p.h/2-cy)<29){c.taken=true;coins++;score+=100;p.vy=Math.min(p.vy,-100);updateHud();sound(720+coins*30,.12);burst(c.x,cy,'#ffc844',10)}}
for(const e of enemies){if(!e.alive)continue;e.x+=e.v*dt;if(e.x<e.min||e.x>e.max){e.v*=-1;e.x=Math.max(e.min,Math.min(e.max,e.x))}const plat=platforms.find(q=>e.x+28>q.x&&e.x<q.x+q.w&&Math.abs(q.y-(e.base||q.y))<1);e.y=(plat?plat.y:400)-23;e.base=e.y;let overlap=p.x<e.x+30&&p.x+p.w>e.x&&p.y<e.y+24&&p.y+p.h>e.y;if(overlap){if(p.vy>80&&p.y+p.h<e.y+18){e.alive=false;p.vy=-jumpPower()*.66;score+=250;sound(300,.15);burst(e.x+15,e.y,'#ff815e',12)}else if(p.invuln<=0){p.invuln=.9;p.vx=p.x<e.x?-260:260;p.vy=-300;coins=Math.max(0,coins-1);updateHud();sound(160,.22);burst(p.x+15,p.y+20,'#ff8065',8)}}}
if(p.invuln>0)p.invuln-=dt;for(const cp of checkpoints){if(!cp.on&&p.x>cp.x){cp.on=true;burst(cp.x,platforms[3].y,'#71d89a',12);sound(850,.15)}}if(p.x>worldW-120)finish(true);
