// distant candy-colored hills
for(let i=0;i<6;i++){let x=((i*230-camera*.16)%1250+1250)%1250-150;ctx.fillStyle=i%2?'#8edbd0':'#a3e4d7';ctx.beginPath();ctx.ellipse(x+90,440,190,115,0,Math.PI,Math.PI*2);ctx.fill()}
for(let i=0;i<8;i++){let x=((i*177-camera*.28)%1150+1150)%1150-80;drawCloud(x,70+(i%3)*66,32+(i%2)*12)}
