for(let i=0;i<5;i++){let x=((i*257-camera*.5)%1400+1400)%1400-200;ctx.fillStyle='#fff9dc';ctx.beginPath();ctx.ellipse(x,510,70,7,0,0,Math.PI*2);ctx.fill()}
