// coins
for(const c of coinItems){if(c.taken)continue;let x=c.x-camera,y=c.y+Math.sin(elapsed*3+c.phase)*4;if(x< -30||x>990)continue;ctx.fillStyle='#d78b2c';ctx.beginPath();ctx.ellipse(x,y+2,8,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd957';ctx.beginPath();ctx.ellipse(x,y,7,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff2a1';ctx.fillRect(x-2,y-7,2,6);ctx.fillStyle='#edaa31';ctx.fillRect(x+3,y-3,2,7)}
