rect(px+3,py+34,11,8,3,'#754a43');rect(px+17,py+34,11,8,3,'#754a43');// overalls
rect(px+5,py+21,20,16,4,'#397fc4');ctx.fillStyle='#ffcc54';ctx.fillRect(px+9,py+23,3,3);ctx.fillRect(px+19,py+23,3,3);// shirt
rect(px+5,py+15,20,11,3,'#f77b56');// face
rect(px+6,py+4,19,16,6,'#ffc58c');ctx.fillStyle='#fff';ctx.fillRect(px+(p.face>0?17:8),py+9,6,6);ctx.fillStyle='#263b4a';ctx.fillRect(px+(p.face>0?20:9),py+11,3,4);// cap
rect(px+3,py+1,23,7,4,'#e95045');rect(px+(p.face>0?17:3),py+6,13,4,2,'#e95045');ctx.fillStyle='#fff';ctx.font='bold 6px sans-serif';ctx.fillText('C',px+12,py+6)}}
// sparkle particles
