if(coins>0){rect(812,18,130,31,9,'#fff7dddc');ctx.fillStyle='#b87327';ctx.font='700 11px "DM Mono",monospace';ctx.fillText('↑ JUMP +'+(coins*18)+'%',825,38)}
}
